   "codice": "extends RefCounted


func run() -> int:
	var is_invincible: bool = true
	var incoming_damage: int = 1
	var final_damage: int = 0
	if not is_invincible:
		final_damage = incoming_damage
	return final_damage
",
   "domanda": "Quanto vale `final_damage` alla fine?",
   "spiegazione": "Essendo `is_invincible` impostato a `true`, la condizione `not is_invincible` risulta falsa. Il danno finale rimane 0, simulando il tempo di intoccabilità."
