   "codice": "extends RefCounted


func run() -> int:
	var current_health: int = 1
	var damage: int = 5
	current_health -= damage
	if current_health < 0:
		current_health = 0
	return current_health
",
   "domanda": "Quanto vale `current_health` alla fine?",
   "spiegazione": "La salute parte da 1 e subisce 5 danni, scendendo a -4. Il controllo successivo interviene azzerandola per evitare valori negativi."
